import {RULES,current,validate,parseCSV,deduplicate,coverage,filterDraws,frequencies,patterns,generate,STRATEGIES,match,csv,easternDate} from './engine.mjs';
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('en-US');
const date=value=>value?new Date(value+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'Never in selection';
const gameName=g=>g==='pb'?'Powerball':'Mega Millions';
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',hot:'<path d="M12 3c2 5-1 5 1 8 1-1 2-2 2-4 6 6 5 14-3 14-7 0-9-7-5-12 0 3 3 3 3 0 0-2 1-4 2-6Z"/>',advanced:'<path d="M4 20V10m8 10V4m8 16v-7M2 22h20"/>',generator:'<path d="m16 3 5 5L8 21l-5-5ZM14 5l5 5M4 4v4M2 6h4M18 16v5m-2-2h5"/>',explore:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5Z"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v5l3 2"/>',saved:'<path d="M6 3h12v18l-6-4-6 4Z"/>',settings:'<path d="m10 3-1 3-3 1-3 3 2 2-1 4 3 1 2 4 3-1 3 1 2-4 3-1-1-4 2-2-3-3-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>'};
const nav=[['dashboard','Dashboard','Overview'],['hot','Hot & Cold','Hot & Cold Numbers'],['advanced','Statistics','Advanced Statistics'],['generator','Generator','Smart Number Generator'],['explore','Explore','Numbers to Explore'],['history','History','Historical Results'],['saved','Saved Tickets','Saved Tickets'],['settings','Data & Settings','Data & Methodology']];
const state={draws:[],provenance:null,game:'pb',route:'dashboard',period:'100',format:'current',from:'',to:'',generated:[],saved:[],sort:'ratio',direction:-1,special:false,historySearch:'',historyDate:'',historyYear:'',historyPage:0,selectedDraw:null,busy:false};
try{state.saved=JSON.parse(localStorage.getItem('lottery-pro-tickets')||'[]').filter(t=>t&&['pb','mm'].includes(t.game)&&Array.isArray(t.white)&&t.white.length===5);const preferences=JSON.parse(localStorage.getItem('lottery-pro-preferences')||'{}');if(['pb','mm'].includes(preferences.game))state.game=preferences.game;if(preferences.period)state.period=preferences.period;}catch{state.saved=[];}
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',3500);}
function saveStorage(){try{localStorage.setItem('lottery-pro-tickets',JSON.stringify(state.saved));return true;}catch{toast('Browser storage is unavailable. Export your tickets to keep them.');return false;}}
function notify(message,error=false){$('notice').innerHTML=message?`<div class="notice ${error?'error':''}">${esc(message)}</div>`:'';}
const balls=(white,special,small=false)=>`<div class="ball-row">${white.map(n=>`<span class="ball ${small?'small':''}">${esc(n)}</span>`).join('')}<span class="ball special ${small?'small':''}">${esc(special)}</span></div>`;
const cardHead=(title,subtitle='',right='')=>`<div class="card-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${right}</div>`;
const selected=()=>filterDraws(state.draws,{game:state.game,period:state.period,format:state.format,from:state.from,to:state.to});
const allGame=()=>state.draws.filter(d=>d.game===state.game&&d.date<=easternDate());
function stats(){const d=selected();return {draws:d,white:frequencies(d,state.game),special:frequencies(d,state.game,true),patterns:patterns(d)};}
function normalizedLabel(){return state.format==='all'?'Normalized across historical matrices':'Expected appearances adjusted for eligible draws';}
function chart(rows,{height=220,expected=false,label='Frequency chart',percent=false}={}) {
  if(!rows.length)return '<div class="empty">No results for this selection.</div>';
  const width=900,left=35,right=10,top=15,bottom=30,plot=height-top-bottom,max=Math.max(1,...rows.map(r=>r.count),...rows.map(r=>r.expected||0))*1.15;
  const step=(width-left-right)/rows.length;
  return `<svg class="freq-chart" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="${esc(label)}">${[0,.25,.5,.75,1].map(t=>`<line class="chart-grid" x1="${left}" x2="${width-right}" y1="${top+plot*(1-t)}" y2="${top+plot*(1-t)}"/><text class="chart-label" x="0" y="${top+plot*(1-t)+3}">${Math.round(max*t)}</text>`).join('')}${rows.map((r,i)=>{const x=left+i*step,y=top+plot*(1-r.count/max);return `<rect class="chart-bar" x="${x+step*.16}" y="${y}" width="${Math.max(1,step*.68)}" height="${plot*r.count/max}" rx="1"><title>${esc(r.label??r.number)}: ${r.count} appearances${r.expected!==undefined?`, expected ${r.expected.toFixed(1)}`:''}</title></rect>${expected&&r.expected!==undefined?`<line x1="${x}" x2="${x+step}" y1="${top+plot*(1-r.expected/max)}" y2="${top+plot*(1-r.expected/max)}" stroke="#afbdce" stroke-width="1" stroke-dasharray="3 2"/>`:''}${rows.length<=18||i%5===0?`<text class="chart-label" x="${x+step/2}" y="${height-8}" text-anchor="middle">${esc(r.label??r.number)}</text>`:''}`;}).join('')}</svg>`;
}
function heatmap(rows){return `<div class="heatmap">${rows.map(n=>`<div class="heat ${n.ratio>1.15?'hot':n.ratio<.85?'cold':'neutral'}" tabindex="0" title="${n.number}: ${n.count} appearances / ${n.eligible} eligible draws; expected ${n.expected.toFixed(1)}; gap ${n.gap}">${n.number}</div>`).join('')}</div><div class="heat-key"><span>Less frequent</span><span class="ramp"></span><span>More frequent</span></div>`;}
function ranking(rows,kind='hot',limit=5){return `<div class="ranking">${rows.slice(0,limit).map((n,i)=>`<div class="rank-row ${kind==='cold'?'cold':''}"><span class="rank-number">${String(i+1).padStart(2,'0')}</span><span class="mini-ball">${n.number}</span><div class="rank-detail">${n.frequency.toFixed(1)}% of eligible draws<span>Expected ${n.expectedPercent.toFixed(1)}% · ${n.gap} draws since seen</span></div><span class="rank-count">${n.count}<small> ×</small></span></div>`).join('')}</div>`;}
function bars(rows,limit=10){const max=Math.max(1,...rows.map(r=>r.count));return `<div class="bar-list">${rows.slice(0,limit).map(r=>`<div class="bar-entry"><span>${esc(r.label)}</span><div class="bar-track"><div style="width:${r.count/max*100}%"></div></div><span>${fmt(r.count)}</span></div>`).join('')}</div>`;}
function nextDrawing(){const now=new Date(),today=easternDate(now),days=state.game==='pb'?[1,3,6]:[2,5];const hour=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',hour12:false,hour:'2-digit',minute:'2-digit'}).format(now);for(let i=0;i<8;i++){const d=new Date(today+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+i);if(days.includes(d.getUTCDay())&&(i>0||hour<(state.game==='pb'?'22:59':'23:00')))return `${d.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})} · ${state.game==='pb'?'10:59':'11:00'} PM ET`;}return 'Check official schedule';}
function renderDashboard(){const {draws,white,special,patterns:p}=stats(),latest=allGame().at(-1),hot=[...white].sort((a,b)=>b.ratio-a.ratio),cold=[...white].filter(n=>n.eligible).sort((a,b)=>a.ratio-b.ratio);const c=coverage(allGame(),state.game);const streak=[...white].sort((a,b)=>b.gap-a.gap)[0];
  return `<div class="stats-row"><div class="stat"><div class="stat-top">Draws analyzed <span class="stat-icon">▥</span></div><div class="stat-value">${fmt(draws.length)}</div><div class="stat-note"><span class="positive">● Real draw records</span> · selected period</div></div><div class="stat"><div class="stat-top">Most frequent white ball <span class="stat-icon">↗</span></div><div class="stat-value">${draws.length?hot[0].number:'—'} <small class="warm">${draws.length?hot[0].frequency.toFixed(1)+'%':''}</small></div><div class="stat-note">${draws.length?hot[0].count+' appearances':'Change your date filters'} · normalized ranking</div></div><div class="stat"><div class="stat-top">Longest current absence <span class="stat-icon">◷</span></div><div class="stat-value">${draws.length?streak.number:'—'} <small class="cool">${draws.length?streak.gap+' draws':''}</small></div><div class="stat-note">Absence does not increase future odds</div></div><div class="stat"><div class="stat-top">Historical coverage <span class="stat-icon">◇</span></div><div class="stat-value">${((c.total/(c.total+c.missing.length))*100).toFixed(1)}<small>%</small></div><div class="stat-note"><span class="positive">${fmt(c.total)} draws</span> · ${c.missing.length} missing scheduled dates</div></div></div>
  <div class="dashboard-grid"><section class="card latest-card">${cardHead('Latest verified drawing',`${gameName(state.game)} · ${date(latest?.date)}`,'<span class="tag verified">● OFFICIAL SOURCE</span>')}${latest?`<div class="latest-row">${balls(latest.white,latest.special)}<div class="next-info">NEXT SCHEDULED DRAW<strong>${nextDrawing()}</strong></div></div><div class="latest-footer"><span>${latest.multiplier?'Multiplier: '+latest.multiplier+'×':'Draw multiplier: not applicable / unavailable'} · Jackpot: unavailable</span><a href="${esc(latest.source)}" target="_blank" rel="noopener noreferrer">View source ↗</a></div>`:'<div class="empty">No verified results available.</div>'}</section>
  <section class="card callout"><div class="symbol">✦</div><span class="eyebrow">A FRESH SET OF POSSIBILITIES</span><h2>Make your next pick.</h2><p>Build a set around historical patterns, or leave it entirely to chance.</p><a class="button primary" href="#generator">Open generator <span>↗</span></a></section>
  <section class="card">${cardHead('White-ball frequency',`${draws.length} draws · ${normalizedLabel()}`,`<div class="chart-legend"><span><i class="legend-dot"></i>Observed</span><span><i class="legend-line"></i>Expected</span></div>`)}${chart(white,{expected:true,label:'Observed and expected white ball appearances'})}<div class="chart-caption"><span>WHITE-BALL NUMBER</span><span>Hover a bar to inspect its count</span></div></section>
  <section class="card">${cardHead('Your number landscape','Frequency relative to the historical expectation')}${heatmap(white)}</section>
  <div class="two-col"><section class="card">${cardHead('Hot white balls','Most frequent relative to expectation','<span class="tag warm">HOT</span>')}${ranking(hot)}</section><section class="card">${cardHead('Cold white balls','Least frequent relative to expectation','<span class="tag cool">COLD</span>')}${ranking(cold,'cold')}</section></div>
  <section class="card">${cardHead('Numbers drawn together','Actual co-occurrences in the selected drawings','<span class="tag">PAIRS</span>')}${bars(p.pairs,5)}<div class="spaced"><a class="link-button" href="#advanced">Explore all patterns ↗</a></div></section>
  <section class="card span-all">${cardHead(state.game==='pb'?'Powerball spotlight':'Mega Ball spotlight','Special balls use a separate pool and a separate expected frequency')}<div class="two-col"><div>${ranking([...special].sort((a,b)=>b.ratio-a.ratio),'hot',5)}</div><div>${chart(special,{expected:true,label:'Special ball appearances'})}</div></div></section></div>`;
}
function renderHot(){const s=stats(),rows=state.special?s.special:s.white;const sorted=[...rows].sort((a,b)=>{let x=a[state.sort]??-1,y=b[state.sort]??-1;return typeof x==='string'?state.direction*x.localeCompare(y):state.direction*(x-y)||a.number-b.number;});const columns=[['number','Number'],['count','Drawn'],['frequency','Frequency'],['expected','Expected count'],['ratio','Obs / exp'],['gap','Current gap'],['last','Last seen'],['longest','Longest gap'],['average','Average gap'],['recent25','Last 25 %'],['recent50','Last 50 %'],['recent100','Last 100 %'],['recent500','Last 500 %'],['trend','Trend'],['z','z score']];
 return `<div class="section-stack"><section class="card">${cardHead('Every number, in context','Blue and red indicate observed fluctuation, not future winning probability.')}<div class="toolbar"><button class="button ${!state.special?'primary':''}" data-ball-type="white">White balls</button><button class="button ${state.special?'primary':''}" data-ball-type="special">${state.game==='pb'?'Powerballs':'Mega Balls'}</button></div><div class="two-col"><div>${heatmap(rows)}</div><div>${chart(rows,{expected:true,label:'Number frequency compared with expectation'})}</div></div></section><section class="card">${cardHead('Frequency & recency table',`${s.draws.length} selected draws. Click a column heading to sort.`)}<div class="table-wrap"><table><thead><tr>${columns.map(([key,label])=>`<th><button class="sort-button" data-sort="${key}">${label} ${state.sort===key?(state.direction<0?'↓':'↑'):''}</button></th>`).join('')}</tr></thead><tbody>${sorted.map(n=>`<tr><td><strong>${n.number}</strong></td><td>${n.count}</td><td>${n.frequency.toFixed(2)}%</td><td>${n.expected.toFixed(1)}</td><td class="${n.ratio>1.15?'warm':n.ratio<.85?'cool':''}">${n.ratio.toFixed(2)}×</td><td>${n.gap}</td><td>${date(n.last)}</td><td>${n.longest}</td><td>${n.average===null?'—':n.average.toFixed(1)}</td><td>${n.recent25.toFixed(1)}</td><td>${n.recent50.toFixed(1)}</td><td>${n.recent100.toFixed(1)}</td><td>${n.recent500.toFixed(1)}</td><td>${n.trend>=0?'+':''}${n.trend.toFixed(2)}</td><td>${n.z.toFixed(2)}</td></tr>`).join('')}</tbody></table></div><p class="method-text spaced">Expected white-ball appearances sum 5 / pool size for every eligible draw; special-ball appearances sum 1 / pool size. Trend compares the last 25 draws’ observed/expected ratio with the selected period. z scores are descriptive standardizations, without multiple-testing correction. They do not show predictive power. Gaps count eligible drawings without an appearance; longest gaps include censored edges, while averages use completed intervals.</p></section></div>`;
}
function renderAdvanced(){const {draws,patterns:p}=stats();return `<div class="section-stack"><div class="stats-row"><div class="stat"><div class="stat-top">Average white-ball sum</div><div class="stat-value">${p.averageSum.toFixed(1)}</div><div class="stat-note">Across ${draws.length} actual drawings</div></div><div class="stat"><div class="stat-top">Consecutive-number draws</div><div class="stat-value">${draws.length?(p.consecutive/draws.length*100).toFixed(1):0}%</div><div class="stat-note">${p.consecutive} draws with adjacent numbers</div></div><div class="stat"><div class="stat-top">Repeated white-ball sets</div><div class="stat-value">${p.repeatedSets.length}</div><div class="stat-note">Identical sets in the selected history</div></div><div class="stat"><div class="stat-top">Repeated balls vs prior draw</div><div class="stat-value">${p.repeat}</div><div class="stat-note">Transitions within the same matrix</div></div></div><div class="two-col"><section class="card">${cardHead('Most common pairs','Each count is an actual historical co-occurrence.')}${bars(p.pairs,10)}</section><section class="card">${cardHead('Most common triplets','All ten three-ball subsets are counted per drawing.')}${bars(p.triplets,10)}</section><section class="card">${cardHead('White-ball sum distribution','Bins span 20 sum units; labels show the lower bound.')}${chart(p.sums,{label:'Distribution of sum of five white balls'})}</section><section class="card">${cardHead('Odd / even distribution','Labels show the number of odd white balls (out of five).')}${chart([...p.odd].sort((a,b)=>+a.label-+b.label),{label:'Odd white ball distribution'})}</section><section class="card">${cardHead('Number spread','Largest minus smallest white ball; bins span ten units.')}${chart(p.spreads,{label:'White ball spread distribution'})}</section><section class="card">${cardHead('Frequency by decade','Counts of individual white-ball appearances.')}${bars(p.decades)}</section><section class="card">${cardHead('Last-digit frequency','Last digits of observed white balls.')}${chart([...p.digits].sort((a,b)=>+a.label-+b.label),{label:'Last digit frequency'})}</section><section class="card">${cardHead('Draws by year','Selected records; incomplete years are not normalized.')}${chart(p.years,{label:'Drawings included by year'})}</section><section class="card">${cardHead('White + special-ball co-occurrences','White ball first, special ball second.')}${bars(p.specialPairs,10)}</section><section class="card">${cardHead('Repeated white-ball combinations','Observed sets that occurred more than once.')}${p.repeatedSets.length?bars(p.repeatedSets,10):'<div class="empty">No repeated five-ball sets in this selection.</div>'}</section></div><div class="notice">These patterns describe the selected history. They do not establish a predictive advantage. Mixed formats have different sum, spread, and pairing opportunities.</div></div>`;}
const strategyDescriptions={random:'Uniform selection without replacement using cryptographically secure browser randomness. Every valid ticket has equal jackpot probability.',hot:'White and special balls are weighted by observed / expected appearances + 0.25. Smoothing keeps unseen numbers eligible.',cold:'Weights use 1 / (observed / expected + 0.25), emphasizing historically infrequent numbers.',mix:'Weights average hot and cold scores, retaining numbers throughout the frequency range.',recent:'Uses observed / expected appearances in the latest selected 25, 50, or 100 draws, plus 0.25 smoothing.',long:'Uses the selected historical period and historical pool sizes: observed / expected + 0.25. Select 5, 10, or 20 years above.',balanced:'Uniform random tickets, retained only when odd/even, low/high, sum, and spread constraints pass. The midpoint is half the current white-ball pool.',pairing:'Seeds a ticket with one of the 30 most common eligible historical pairs, weighted by its actual co-occurrence count.',custom:'Enter optional number:weight values. Unspecified numbers have weight 1; zero excludes a number from weighted selection.',ensemble:'Adds hot, cold, and recent weight scores using the blend values below. It does not improve the odds of a valid ticket.'};
function ticketMarkup(t,i,{saved=false}={}){return `<article class="ticket"><div class="ticket-top"><strong>${saved?esc(t.name||'My combination'):`Combination ${String(i+1).padStart(2,'0')}`}${t.favorite?' <span class="favorite">★</span>':''}</strong><div class="ticket-actions">${saved?`<button class="button subtle" data-favorite="${esc(t.id)}" aria-label="Toggle favorite">${t.favorite?'★':'☆'}</button><button class="button subtle" data-delete="${esc(t.id)}">Delete</button>`:`<button class="button subtle" data-save="${i}">☆ Save</button>`}<button class="button subtle" data-copy="${saved?'saved:':''}${i}">Copy</button></div></div>${balls(t.white,t.special)}<p class="ticket-frequencies">${saved?gameName(t.game)+' · ':''}${esc(STRATEGIES[t.strategy]||'Manual entry')}${t.frequencies?` · Selected-period frequencies: ${t.white.map((n,j)=>n+': '+t.frequencies[j].toFixed(1)+'%').join(' / ')}`:''}${t.duplicate?' · Duplicate combination':''}</p><div class="ticket-meta"><span>SUM <b>${t.sum??t.white.reduce((a,b)=>a+b,0)}</b></span><span>ODD / EVEN <b>${t.white.filter(n=>n%2).length} / ${t.white.filter(n=>!(n%2)).length}</b></span><span>LOW / HIGH <b>${t.white.filter(n=>n<=Math.floor(current(t.game).white/2)).length} / ${t.white.filter(n=>n>Math.floor(current(t.game).white/2)).length}</b></span><span>SPREAD <b>${t.white[4]-t.white[0]}</b></span></div>${saved?`<div class="detail-box">${savedCheck(t)}</div>`:''}</article>`;}
function savedCheck(t){const d=allGame().filter(d=>d.game===t.game);const latest=d.at(-1);if(!latest)return 'Select this ticket’s game to check the latest drawing.';const m=match(t,latest);let best={white:-1,special:false},bestDate=null;for(const draw of d){if(t.white.some(n=>n>RULES[t.game].findLast(r=>r.start<=draw.date).white)||t.special>RULES[t.game].findLast(r=>r.start<=draw.date).special)continue;const result=match(t,draw);if(result.white>best.white||result.white===best.white&&result.special&&!best.special){best=result;bestDate=draw.date;}}
 return `Latest (${date(latest.date)}): <strong>${m.white} white ${m.special?'+ special ball':'· no special ball'}</strong><br>Best historical match: ${best.white} white ${best.special?'+ special ball':''} · ${date(bestDate)}<br>Prize estimate unavailable; saved combinations are not official lottery entries.`;}
function renderGenerator(){return `<div class="generator-layout"><section class="card">${cardHead('Build your combination',`Current ${gameName(state.game)} matrix: 5 / ${current(state.game).white} + 1 / ${current(state.game).special}`)}<form id="generator-form" class="form-stack"><label>Generation strategy<select id="strategy">${Object.entries(STRATEGIES).map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select></label><div class="strategy-info" id="strategy-info">${strategyDescriptions.random}</div><div class="form-row"><label>Number of tickets<select id="ticket-count">${[1,5,10,20,50,100].map(n=>`<option value="${n}" ${n===5?'selected':''}>${n} tickets</option>`).join('')}</select></label><label>Recent window<select id="trend-window"><option value="25">25 draws</option><option value="50">50 draws</option><option value="100">100 draws</option></select></label></div><label class="inline-check"><input type="checkbox" id="unique" checked> Duplicate-free batch</label><details><summary>Favorite & excluded numbers</summary><div class="form-stack"><label>Lock white balls (comma separated)<input id="locked" placeholder="e.g. 7, 21" inputmode="numeric"></label><label>Exclude white balls<input id="excluded" placeholder="e.g. 1, 13" inputmode="numeric"></label><label>Lock special ball<input id="special-locked" type="number" min="1" max="${current(state.game).special}" placeholder="Optional"></label><label>Exclude special balls<input id="special-excluded" placeholder="e.g. 2, 8" inputmode="numeric"></label></div></details><details><summary>Balanced strategy constraints</summary><div class="form-stack"><div class="form-row"><label>Min sum<input id="min-sum" type="number" value="80"></label><label>Max sum<input id="max-sum" type="number" value="250"></label></div><div class="form-row"><label>Min odd balls<input id="min-odd" type="number" value="2" min="0" max="5"></label><label>Max odd balls<input id="max-odd" type="number" value="3" min="0" max="5"></label></div><div class="form-row"><label>Min low balls<input id="min-low" type="number" value="2" min="0" max="5"></label><label>Max low balls<input id="max-low" type="number" value="3" min="0" max="5"></label></div><div class="form-row"><label>Min spread<input id="min-spread" type="number" value="20"></label><label>Max spread<input id="max-spread" type="number" value="68"></label></div></div></details><details><summary>Custom weights & ensemble</summary><div class="form-stack"><label>White-ball weights (number:weight)<input id="custom-weights" placeholder="7:3, 21:2, 13:0"></label><label>Special-ball weights<input id="special-weights" placeholder="4:2, 8:0"></label><div class="form-row"><label>Hot blend weight<input id="blend-hot" type="number" min="0" value="1"></label><label>Cold blend weight<input id="blend-cold" type="number" min="0" value="1"></label></div><label>Recent blend weight<input id="blend-recent" type="number" min="0" value="1"></label></div></details><button type="submit" class="button primary" id="generate-submit">✦ Generate numbers</button><p class="method-text">Weights change your selection preferences. They do not increase a valid ticket’s winning probability.</p></form></section><section class="card">${cardHead('Your generated tickets','Explore, save, or export your combinations.','<span class="tag">CURRENT MATRIX</span>')}<div class="toolbar"><button class="button subtle" id="generate-again">↻ Generate again</button><button class="button subtle" id="export-tickets">Export CSV</button><button class="button subtle" id="print-tickets">Print</button></div><div id="generated-tickets">${state.generated.length?renderTicketList():'<div class="empty"><div style="font-size:42px;color:var(--accent);margin-bottom:15px">✦</div><h3>Your next set starts here.</h3><p>Choose a strategy, then generate your tickets.<br>All selections stay within the current game’s ranges.</p></div>'}</div></section></div>`;}
function renderTicketList(){return `<div class="ticket-list">${state.generated.filter(t=>t.game===state.game).map((t,i)=>ticketMarkup(t,state.generated.indexOf(t))).join('')}</div>`;}
function renderExplore(){const {white,patterns:p,draws}=stats();const hot=[...white].sort((a,b)=>b.ratio-a.ratio),cold=[...white].filter(n=>n.eligible).sort((a,b)=>a.ratio-b.ratio),rising=[...white].sort((a,b)=>b.trend-a.trend),gaps=[...white].sort((a,b)=>b.gap-a.gap),near=[...white].filter(n=>n.eligible).sort((a,b)=>Math.abs(a.ratio-1)-Math.abs(b.ratio-1));return `<div class="section-stack"><div class="notice">Explore historical characteristics, not predictions. Rankings are recalculated from ${draws.length} selected draws.</div><div class="three-col"><section class="card">${cardHead('Historically frequent','Ranked by observed / expected appearances.')}${ranking(hot,'hot',10)}</section><section class="card">${cardHead('Historically infrequent','Ranked by lowest observed / expected ratio.')}${ranking(cold,'cold',10)}</section><section class="card">${cardHead('Recent risers','Latest 25 draws’ ratio minus the period’s ratio.')}${ranking(rising,'hot',10)}</section><section class="card">${cardHead('Longest current absence','Drawings since last appearance; not “due” to win.')}${ranking(gaps,'cold',10)}</section><section class="card">${cardHead('Near historical expectation','Smallest absolute distance from an observed/expected ratio of 1.')}${ranking(near,'hot',10)}</section><section class="card">${cardHead('Frequent pairings','Actual co-occurrences, with no inferred relationships.')}${bars(p.pairs,10)}<div class="spaced"><a class="button primary" href="#generator">Explore with the generator ↗</a></div></section></div></div>`;}
function historyFiltered(){const nums=state.historySearch.trim().split(/[\s,]+/).filter(Boolean).map(Number);return selected().filter(d=>(!state.historyDate||d.date===state.historyDate)&&(!state.historyYear||d.date.startsWith(state.historyYear))&&nums.every(n=>d.white.includes(n))).reverse();}
function renderHistory(){const data=historyFiltered(),per=50,pages=Math.max(1,Math.ceil(data.length/per));state.historyPage=Math.min(state.historyPage,pages-1);return `<section class="card">${cardHead('The drawing archive','Search actual verified results. Number searches match white balls only.',`<button class="button subtle" id="export-history">↓ Export CSV</button>`)}<div class="search-row"><input id="history-search" aria-label="Search white balls" placeholder="Find a number, pair, or triplet · e.g. 7, 21" value="${esc(state.historySearch)}"><input id="history-date" type="date" aria-label="Drawing date" value="${esc(state.historyDate)}"><select id="history-year" aria-label="Year"><option value="">All years</option>${[...new Set(allGame().map(d=>d.date.slice(0,4)))].reverse().map(y=>`<option ${state.historyYear===y?'selected':''}>${y}</option>`).join('')}</select></div><p class="page-badge">${fmt(data.length)} matching draws · page ${state.historyPage+1} of ${pages} · global filters apply</p><div class="table-wrap"><table><thead><tr><th>Drawing date</th><th>Winning numbers</th><th>Multiplier</th><th>Matrix</th><th>Source</th><th></th></tr></thead><tbody>${data.slice(state.historyPage*per,(state.historyPage+1)*per).map(d=>`<tr><td>${date(d.date)}</td><td>${balls(d.white,d.special,true)}</td><td>${d.multiplier?d.multiplier+'×':'—'}</td><td>5 / ${RULES[state.game].findLast(r=>r.start<=d.date).white} + 1 / ${RULES[state.game].findLast(r=>r.start<=d.date).special}</td><td><a href="${esc(d.source)}" target="_blank" rel="noopener noreferrer">${d.source.includes('colorado')?'Colorado':'Texas'} ↗</a></td><td><button class="link-button" data-detail="${d.date}">Details</button></td></tr>`).join('')}</tbody></table>${!data.length?'<div class="empty">No drawings match these filters. Try a wider period or another game format.</div>':''}</div><div class="toolbar spaced"><button class="button subtle" id="prev-page" ${state.historyPage===0?'disabled':''}>← Previous</button><button class="button subtle" id="next-page" ${state.historyPage===pages-1?'disabled':''}>Next →</button></div><div id="draw-detail">${state.selectedDraw?renderDetail():''}</div></section>`;}
function renderDetail(){const d=allGame().find(d=>d.date===state.selectedDraw);if(!d)return '';const prior=allGame().filter(x=>x.date<d.date&&x.version===d.version);const f=frequencies(prior,state.game);return `<div class="detail-box"><h3>${date(d.date)} · ${gameName(d.game)}</h3><div class="spaced">${balls(d.white,d.special)}</div><p class="spaced">Prior drawings in this matrix: ${prior.length}. White-ball appearances before this drawing: ${d.white.map(n=>`${n}: ${f[n-1]?.count||0}`).join(' · ')}.</p><p>Sum: ${d.white.reduce((a,b)=>a+b,0)} · Spread: ${d.white[4]-d.white[0]} · Jackpot / winner details: not included in this dataset.</p><p>Source verified at ${esc(d.verifiedAt)} · Historical matrix effective ${date(d.version)}.</p></div>`;}
function renderSaved(){const rows=state.saved.filter(t=>t.game===state.game).sort((a,b)=>Number(b.favorite)-Number(a.favorite));return `<div class="section-stack"><section class="card">${cardHead('Keep your favorite combinations','Saved locally in this browser. A saved combination is not a lottery entry.',`<span class="tag">${rows.length} SAVED</span>`)}<div class="toolbar"><button class="button subtle" id="export-saved">↓ Export saved CSV</button><button class="button subtle" id="print-tickets">Print</button></div><form id="manual-form" class="form-stack"><div class="form-row"><label>Ticket name<input id="ticket-name" placeholder="My favorite numbers" maxlength="60"></label><label>Five white balls + special ball<input id="manual-numbers" placeholder="7, 21, 34, 42, 56 + 9" required></label></div><button class="button primary" style="align-self:flex-start">+ Save manual combination</button></form></section><section class="card">${cardHead('Saved tickets & result checks','Compared with the latest published results and compatible historical matrices.')}<div class="ticket-list">${rows.map(t=>ticketMarkup(t,state.saved.indexOf(t),{saved:true})).join('')||'<div class="empty">No saved tickets for this game yet.<br>Generate a set or enter your own combination above.</div>'}</div></section></div>`;}
function renderSettings(){const c=coverage(allGame(),state.game),p=state.provenance,tx=p.sources.find(s=>s.game===state.game&&s.name==='Texas Lottery');return `<div class="section-stack"><div class="two-col"><section class="card">${cardHead('Data coverage',`Requested history: October 2006 to the present. ${gameName(state.game)}.`,'<span class="tag verified">VERIFIED SNAPSHOT</span>')}<div class="stat-value">${fmt(c.total)} <small>official drawings</small></div><div class="coverage-track"><div style="width:${c.total/(c.total+c.missing.length)*100}%"></div></div><p class="method-text">${date(c.first)} – ${date(c.last)}<br>${c.missing.length} expected dates currently missing.<br>Last retrieval: ${new Date(p.updatedAt).toLocaleString('en-US',{timeZone:'America/New_York'})} ET.</p>${c.missing.length?`<details class="spaced"><summary>Missing dates</summary><p class="method-text">${c.missing.map(date).join(' · ')}</p></details>`:''}<p class="method-text spaced">Scheduled dates are checked against the game’s drawing weekdays. Results from today are treated as missing only after 11:30 PM ET. Delayed or rescheduled drawings require checking with the operator.</p></section><section class="card">${cardHead('Official sources','No simulated or fabricated historical drawings.')}<div class="source-list"><div class="source-item"><a href="${esc(tx?.url)}" target="_blank" rel="noopener noreferrer">Texas Lottery CSV ↗</a><br>Powerball: February 3, 2010 onward.<br>Mega Millions: December 5, 2003 onward.<br><b>Dataset validated against historical matrices</b></div><div class="source-item"><a href="https://www.coloradolottery.com/en/games/powerball/drawings/2006-10/" target="_blank" rel="noopener noreferrer">Colorado Lottery archive ↗</a><br>Fills Powerball’s October 2006 – January 2010 history.<br><b>Monthly official archive pages retrieved</b></div></div></section></div><section class="card">${cardHead('A small app, transparent methods','The data and mathematics behind the dashboard.')}<div class="method-text"><p><strong>Snapshot updates.</strong> This simple app ships a verified data snapshot. Reload fetches the latest published files; it does not fetch new drawings directly from lottery operators. The included <code>npm run data:refresh</code> script updates the official files before republishing. Source retrieval timestamps and SHA-256 hashes are stored in the downloadable provenance file. Automatic background sync is not enabled.</p><p><strong>Historical rules.</strong> Each drawing uses the number matrix effective on its date. Expected white-ball appearances are the sum of 5 / white-pool size; expected special-ball appearances are the sum of 1 / special-pool size. Numbers outside a historical pool receive no exposure for that drawing. Hot and cold rankings use observed / expected appearances so format changes are explicit. Choose “Current format” for the clearest comparison.</p><p><strong>Generation.</strong> Pure Random uses the browser’s cryptographically secure randomness with rejection sampling to avoid modulo bias, then selects white balls without replacement. Weighted strategies are sampling preferences applied to real historical frequencies. Constraints can make some batches impossible; the app reports that instead of silently relaxing them.</p><p><strong>Statistical interpretation.</strong> Drawings are independent in a fair lottery. Hot, cold, and overdue numbers have no greater chance in the next drawing. Every valid combination has the same jackpot probability. z scores are uncorrected descriptive deviations, not prediction scores.</p><p><strong>Unavailable values.</strong> No current jackpot feed, prize estimates, winner claims, or backtest profit claims are included. The post-April 2025 Mega Millions multiplier is assigned to purchased plays, so there is no drawing-wide multiplier for those records.</p><p><strong>Saved tickets.</strong> Tickets are stored only in this browser’s local storage. Export them for a backup. Clearing browser storage removes them. They are not purchased tickets or official entries.</p><p><a href="data/provenance.json" download>Download source provenance ↗</a> · <a href="https://www.powerball.com" target="_blank" rel="noopener noreferrer">Powerball official site ↗</a> · <a href="https://www.megamillions.com" target="_blank" rel="noopener noreferrer">Mega Millions official site ↗</a></p></div><div class="table-wrap"><table><thead><tr><th>First drawing in version</th><th>White pool</th><th>Special pool</th></tr></thead><tbody>${RULES[state.game].map(r=>`<tr><td>${date(r.start)}${r.start==='2006-10-01'?' (coverage start)':''}</td><td>5 of ${r.white}</td><td>1 of ${r.special}</td></tr>`).join('')}</tbody></table></div></section></div>`;}
function render(){if(!state.draws.length)return;state.route=nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'dashboard';const route=nav.find(n=>n[0]===state.route);$('breadcrumb').textContent=route[2];$('page-title').textContent=state.route==='dashboard'?'Your numbers. In perspective.':route[2];$('page-subtitle').textContent={dashboard:'Explore the history. Understand the patterns. Make your own picks.',hot:'A clear look at historical frequency, recency, and the gaps between.',advanced:'The combinations and distributions behind the drawings.',generator:'Your preferences. Real history. A fresh set of possibilities.',explore:'Follow your curiosity through the numbers. Nothing here is a prediction.',history:'Twenty years of official results, one drawing at a time.',saved:'Keep your combinations and compare them with real results.',settings:'Know where the numbers come from and how the statistics work.'}[state.route];$('navigation').innerHTML=nav.map(([id,label])=>`<a href="#${id}" class="nav-item ${id===state.route?'active':''}" data-route="${id}" ${id===state.route?'aria-current="page"':''}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true">${icons[id]}</svg><span>${label}</span></a>`).join('');document.documentElement.style.setProperty('--accent',state.game==='pb'?'#ee615d':'#d8ab55');document.documentElement.style.setProperty('--accent-soft',state.game==='pb'?'#ee615d18':'#d8ab5518');document.querySelectorAll('[data-game]').forEach(b=>{b.classList.toggle('active',b.dataset.game===state.game);b.setAttribute('aria-pressed',String(b.dataset.game===state.game));});$('period').value=state.period;$('format').innerHTML=`<option value="current">Current format</option><option value="all">All formats · normalized</option>${RULES[state.game].map(r=>`<option value="${r.start}">${r.start.slice(0,4)} · 5/${r.white} + 1/${r.special}</option>`).join('')}`;$('format').value=state.format;$('custom-dates').hidden=state.period!=='custom';const renders={dashboard:renderDashboard,hot:renderHot,advanced:renderAdvanced,generator:renderGenerator,explore:renderExplore,history:renderHistory,saved:renderSaved,settings:renderSettings};$('content').innerHTML=renders[state.route]();bindPage();try{localStorage.setItem('lottery-pro-preferences',JSON.stringify({game:state.game,period:state.period}));}catch{}
}
function nums(value){if(!value.trim())return [];const n=value.trim().split(/[\s,]+/).map(Number);if(n.some(x=>!Number.isInteger(x)))throw new Error('Numbers must be whole numbers separated by commas.');return n;}
function parseWeights(value,max){if(!value.trim())return {};const result={};for(const pair of value.split(',')){const parts=pair.trim().split(':');if(parts.length!==2)throw new Error('Use number:weight pairs, such as 7:3, 21:2');const [n,w]=parts.map(Number);if(!Number.isInteger(n)||n<1||n>max||!Number.isFinite(w)||w<0)throw new Error('Custom weights must use valid numbers and nonnegative values.');result[n]=w;}return result;}
function runGenerate(){try{const strategy=$('strategy').value;if(strategy!=='random'&&strategy!=='balanced'&&!selected().length)throw new Error('No historical data in this selection. Widen your filters or choose Pure Random.');const button=$('generate-submit');button.disabled=true;const config={strategy,count:+$('ticket-count').value,trendWindow:+$('trend-window').value,unique:$('unique').checked,locked:nums($('locked').value),excluded:nums($('excluded').value),specialLocked:$('special-locked').value?+$('special-locked').value:null,specialExcluded:nums($('special-excluded').value),weights:parseWeights($('custom-weights').value,current(state.game).white),specialWeights:parseWeights($('special-weights').value,current(state.game).special),minSum:+$('min-sum').value,maxSum:+$('max-sum').value,minOdd:+$('min-odd').value,maxOdd:+$('max-odd').value,minLow:+$('min-low').value,maxLow:+$('max-low').value,minSpread:+$('min-spread').value,maxSpread:+$('max-spread').value,ensemble:{hot:+$('blend-hot').value,cold:+$('blend-cold').value,recent:+$('blend-recent').value}};setTimeout(()=>{try{state.generated=generate(selected(),state.game,config);$('generated-tickets').innerHTML=renderTicketList();notify('');toast(`${state.generated.length} combinations generated`);bindTicketActions();}catch(error){notify(error.message,true);}finally{button.disabled=false;}},20);}catch(error){notify(error.message,true);}}
function download(name,content,type='text/csv'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000);}
function exportTickets(tickets){if(!tickets.length){toast('No tickets to export yet.');return;}download('lottery-tickets.csv','game,n1,n2,n3,n4,n5,special,strategy,name\n'+tickets.map(t=>[gameName(t.game),...t.white,t.special,STRATEGIES[t.strategy]||'Manual',`"${(t.name||'').replaceAll('"','""').replace(/^[=+@-]/,"'")}"`].join(',')).join('\n'));}
function storeTicket(ticket,name){const existing=state.saved.find(t=>t.game===ticket.game&&t.white.join(',')===ticket.white.join(',')&&t.special===ticket.special);if(existing){toast('This combination is already saved.');return;}state.saved.push({...ticket,id:crypto.randomUUID(),name:name||`${gameName(ticket.game)} pick ${state.saved.length+1}`,favorite:false});saveStorage();toast('Ticket saved in this browser.');}
function bindTicketActions(){document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>storeTicket(state.generated[+b.dataset.save]));document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const key=b.dataset.copy,t=key.startsWith('saved:')?state.saved[+key.slice(6)]:state.generated[+key];try{await navigator.clipboard.writeText(`${gameName(t.game)}: ${t.white.join(' ')} + ${t.special}`);toast('Numbers copied.');}catch{toast('Clipboard unavailable. Use CSV export instead.');}});document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>{const ticket=state.saved.find(t=>t.id===b.dataset.favorite);ticket.favorite=!ticket.favorite;saveStorage();render();});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{state.saved=state.saved.filter(t=>t.id!==b.dataset.delete);saveStorage();render();toast('Ticket removed.');});}
function bindPage(){bindTicketActions();if($('generator-form')){$('generator-form').onsubmit=e=>{e.preventDefault();runGenerate();};$('generate-again').onclick=runGenerate;$('strategy').onchange=()=>{$('strategy-info').textContent=strategyDescriptions[$('strategy').value];};$('export-tickets').onclick=()=>exportTickets(state.generated);$('print-tickets').onclick=()=>window.print();}if($('manual-form')){$('manual-form').onsubmit=e=>{e.preventDefault();try{const split=$('manual-numbers').value.split('+');if(split.length!==2)throw new Error('Enter five white balls, then + and the special ball.');const white=nums(split[0]).sort((a,b)=>a-b),special=+split[1];const rule=current(state.game);if(white.length!==5||new Set(white).size!==5||white.some(n=>n<1||n>rule.white)||!Number.isInteger(special)||special<1||special>rule.special)throw new Error(`Use five unique white balls from 1–${rule.white} and one special ball from 1–${rule.special}.`);storeTicket({game:state.game,white,special,strategy:'manual',createdAt:new Date().toISOString()},$('ticket-name').value.trim());notify('');render();}catch(error){notify(error.message,true);}};$('export-saved').onclick=()=>exportTickets(state.saved.filter(t=>t.game===state.game));$('print-tickets').onclick=()=>window.print();}
 document.querySelectorAll('[data-ball-type]').forEach(b=>b.onclick=()=>{state.special=b.dataset.ballType==='special';render();});document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{state.direction=state.sort===b.dataset.sort?-state.direction:-1;state.sort=b.dataset.sort;render();});
 if($('history-search')){let timer;$('history-search').oninput=e=>{const val=e.target.value;clearTimeout(timer);timer=setTimeout(()=>{state.historySearch=val;state.historyPage=0;render();$('history-search').focus();$('history-search').setSelectionRange(val.length,val.length);},350);};$('history-date').onchange=e=>{state.historyDate=e.target.value;state.historyPage=0;render();};$('history-year').onchange=e=>{state.historyYear=e.target.value;state.historyPage=0;render();};$('export-history').onclick=()=>download('lottery-draw-history.csv',csv(historyFiltered()));$('prev-page').onclick=()=>{state.historyPage--;render();};$('next-page').onclick=()=>{state.historyPage++;render();};document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{state.selectedDraw=b.dataset.detail;$('draw-detail').innerHTML=renderDetail();$('draw-detail').scrollIntoView({behavior:'smooth',block:'nearest'});});}
}
async function loadData(){state.busy=true;$('reload').disabled=true;try{const get=async path=>{const r=await fetch(path,{cache:'no-store'});if(!r.ok)throw new Error(`Could not load ${path}.`);return r;};const [pb,mm,early,provenance]=await Promise.all([get('data/powerball.csv').then(r=>r.text()),get('data/megamillions.csv').then(r=>r.text()),get('data/early-powerball.json').then(r=>r.json()),get('data/provenance.json').then(r=>r.json())]);state.provenance=provenance;state.draws=deduplicate([...parseCSV(pb,'pb',provenance.sources.find(s=>s.name==='Texas Lottery'&&s.game==='pb').retrievedAt),...parseCSV(mm,'mm',provenance.sources.find(s=>s.name==='Texas Lottery'&&s.game==='mm').retrievedAt),...early.map(d=>validate({...d,game:'pb'}))]);render();const age=(Date.now()-new Date(provenance.updatedAt))/86400000;if(age>3)notify(`This published snapshot was retrieved ${Math.floor(age)} days ago. View Data & Settings for update instructions.`);}catch(error){notify(error.message,true);if(!state.draws.length)$('content').innerHTML='<div class="empty">Data could not be loaded. Reload to try again.<br>Use the local web server or the published app, rather than opening index.html directly.</div>';}finally{state.busy=false;$('reload').disabled=false;}}
document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>{if(state.game===b.dataset.game)return;state.game=b.dataset.game;state.format='current';state.selectedDraw=null;state.historyPage=0;state.special=false;notify('');render();});$('period').onchange=e=>{state.period=e.target.value;state.historyPage=0;render();};$('format').onchange=e=>{state.format=e.target.value;state.historyPage=0;render();};for(const key of ['from','to'])$(key).onchange=e=>{state[key]=e.target.value;if(state.from&&state.to&&state.from>state.to){notify('The start date must be before the end date.',true);return;}notify('');render();};$('quick-generate').onclick=()=>{location.hash='generator';};$('reload').onclick=async()=>{notify('');await loadData();if(state.draws.length)toast('Published drawing files reloaded.');};window.addEventListener('hashchange',()=>{notify('');render();window.scrollTo(0,0);});
await loadData();
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js').catch(()=>{});
